import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader reader = new InputReader(inputStream);
        PrintWriter writer = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.run(reader, writer);
        writer.close();
    }

    static class Solver {
        static final int MOD = 998244353;

        void run(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int[] base = new int[10];
            for (int i = 0; i < k; i++) {
                base[in.nextInt()] = 1;
            }
            int[] power = {1};
            int exponent = n / 2;
            for (int bit = 1; exponent > 0; bit <<= 1) {
                if ((exponent & 1) != 0) {
                    power = multiply(power, base, MOD);
                }
                exponent >>= 1;
                if (exponent > 0) {
                    base = multiply(base, base, MOD);
                }
            }
            long sum = 0;
            for (int coeff : power) {
                sum = (sum + (long) coeff * coeff) % MOD;
            }
            out.println((int) sum);
        }

        static int[] multiply(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);
            double[] aR = new double[n];
            double[] aI = new double[n];
            for (int i = 0; i < a.length; i++) {
                int v = (a[i] % mod + mod) % mod;
                aR[i] = v & 0x7FFF;
                aI[i] = v >> 15;
            }
            fft(aR, aI, false);

            double[] bR = new double[n];
            double[] bI = new double[n];
            if (a == b) {
                System.arraycopy(aR, 0, bR, 0, n);
                System.arraycopy(aI, 0, bI, 0, n);
            } else {
                for (int i = 0; i < b.length; i++) {
                    int v = (b[i] % mod + mod) % mod;
                    bR[i] = v & 0x7FFF;
                    bI[i] = v >> 15;
                }
                fft(bR, bI, false);
            }

            double[] fR = new double[n];
            double[] fI = new double[n];
            double[] gR = new double[n];
            double[] gI = new double[n];

            double inv = 0.25 / n;
            for (int i = 0; i < n; i++) {
                int j = (n - i) & (n - 1);

                double a1r = aR[i] + aR[j];
                double a1i = aI[i] - aI[j];
                double a2r = aI[i] + aI[j];
                double a2i = aR[j] - aR[i];

                double b1r = (bR[i] + bR[j]) * inv;
                double b1i = (bI[i] - bI[j]) * inv;
                double b2r = (bI[i] + bI[j]) * inv;
                double b2i = (bR[j] - bR[i]) * inv;

                fR[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
                fI[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;

                gR[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
                gI[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
            }

            fft(fR, fI, true);
            fft(gR, gI, true);
            int[] res = new int[need];
            for (int i = 0; i < need; i++) {
                long aa = (long) (fR[i] + 0.5);
                long bb = (long) (gR[i] + 0.5);
                long cc = (long) (fI[i] + 0.5);
                res[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
            }
            return res;
        }

        static void fft(double[] re, double[] im, boolean inverse) {
            int n = re.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift);
                if (i < j) {
                    double t = re[i];
                    re[i] = re[j];
                    re[j] = t;
                    t = im[i];
                    im[i] = im[j];
                    im[j] = t;
                }
            }
            for (int len = 2; len <= n; len <<= 1) {
                int half = len >> 1;
                double[] cos = new double[half];
                double[] sin = new double[half];
                double ang = 2 * Math.PI / len * (inverse ? -1 : 1);
                for (int i = 0; i < half; i++) {
                    cos[i] = Math.cos(ang * i);
                    sin[i] = Math.sin(ang * i);
                }
                for (int i = 0; i < n; i += len) {
                    for (int j = 0; j < half; j++) {
                        double uR = re[i + j];
                        double uI = im[i + j];
                        double vR = re[i + j + half] * cos[j] - im[i + j + half] * sin[j];
                        double vI = re[i + j + half] * sin[j] + im[i + j + half] * cos[j];
                        re[i + j] = uR + vR;
                        im[i + j] = uI + vI;
                        re[i + j + half] = uR - vR;
                        im[i + j + half] = uI - vI;
                    }
                }
            }
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
